package org.sleepwell.app;
import android.content.ContentValues;import android.database.sqlite.SQLiteDatabase;import org.json.*;import java.util.*;import java.util.function.BooleanSupplier;
/** Separate secondary evidence. Root integration calls create/export/validate/restore for its shared schema. */
final class PirStore {
 static final List<String> TABLES=List.of("pir_runs","pir_samples");static final Set<String> STATES=Set.of("off","active","paused","complete","interrupted","error"),ERRORS=Set.of("","CONFIG","CONNECTION","STORAGE","OWNER_LOST");
 static void create(SQLiteDatabase db){db.execSQL("CREATE TABLE pir_runs(session INTEGER PRIMARY KEY,policy TEXT NOT NULL,state TEXT NOT NULL,error TEXT NOT NULL,token TEXT NOT NULL)");db.execSQL("CREATE TABLE pir_samples(id INTEGER PRIMARY KEY,session INTEGER NOT NULL,time INTEGER NOT NULL,elapsed_ms INTEGER NOT NULL,state INTEGER,quality TEXT NOT NULL,age_ms INTEGER,latency_ms INTEGER NOT NULL)");db.execSQL("CREATE INDEX pir_sample_session ON pir_samples(session,time)");db.execSQL("CREATE TRIGGER delete_pir_record AFTER DELETE ON sessions BEGIN DELETE FROM pir_samples WHERE session=OLD.id; DELETE FROM pir_runs WHERE session=OLD.id; END");}
 static void begin(Store store,long session,String policy,String token,String state,String error){if(!STATES.contains(state)||!ERRORS.contains(error))throw new IllegalArgumentException("Invalid PIR run.");if(!policy.isEmpty())PirConfig.validatePolicy(policy);if(store.rows("SELECT id FROM sessions WHERE id=? AND end IS NULL AND source='tracked'",Long.toString(session)).size()!=1)throw new IllegalStateException("Recording changed before PIR admission.");ContentValues v=new ContentValues();v.put("session",session);v.put("policy",policy);v.put("state",state);v.put("error",error);v.put("token",token);store.getWritableDatabase().insertOrThrow("pir_runs",null,v);}
 static void status(Store store,long session,String token,String state,String error){if(!STATES.contains(state)||!ERRORS.contains(error))throw new IllegalArgumentException("Invalid PIR outcome.");store.getWritableDatabase().execSQL("UPDATE pir_runs SET state=?,error=? WHERE session=? AND token=?",new Object[]{state,error,session,token});}
 static void append(Store store,long session,String token,long time,long elapsed,PirHttp.Reading reading,BooleanSupplier current){checkReading(reading.state,reading.quality,reading.age,reading.latency);SQLiteDatabase db=store.getWritableDatabase();db.beginTransaction();try{List<JSONObject> rows=store.rows("SELECT s.start,s.end,r.token,r.state FROM sessions s JOIN pir_runs r ON r.session=s.id WHERE s.id=? AND s.source='tracked'",Long.toString(session));if(rows.size()!=1||!rows.get(0).isNull("end")||!rows.get(0).optString("token").equals(token)||!rows.get(0).optString("state").equals("active")||!current.getAsBoolean())throw new IllegalStateException("PIR recording owner changed.");long start=rows.get(0).optLong("start");if(time<start||elapsed!=time-start||elapsed>SensorProvenance.MAX_SESSION||!store.rows("SELECT id FROM tracking_pauses WHERE session=? AND start<=CAST(? AS INTEGER) AND (end IS NULL OR end>CAST(? AS INTEGER))",Long.toString(session),Long.toString(time),Long.toString(time)).isEmpty())throw new IllegalArgumentException("PIR sample is outside active recording.");List<JSONObject> previous=store.rows("SELECT MAX(time) AS time,COUNT(*) AS n FROM pir_samples WHERE session=?",Long.toString(session));if(previous.get(0).optLong("n")>=10000||!previous.get(0).isNull("time")&&time<=previous.get(0).optLong("time"))throw new IllegalStateException("PIR sample limit or ordering changed.");ContentValues v=new ContentValues();v.put("session",session);v.put("time",time);v.put("elapsed_ms",elapsed);v.put("state",reading.state);v.put("quality",reading.quality);v.put("age_ms",reading.age);v.put("latency_ms",reading.latency);db.insertOrThrow("pir_samples",null,v);if(!current.getAsBoolean())throw new IllegalStateException("PIR owner changed while saving.");db.setTransactionSuccessful();}finally{db.endTransaction();}}
 static void recover(SQLiteDatabase db,long session){db.execSQL("UPDATE pir_runs SET state='interrupted',token='' WHERE session=? AND state IN ('active','paused')",new Object[]{session});}
 static void checkReading(Integer state,String quality,Long age,long latency){if(!PirHttp.QUALITY.contains(quality)||quality.equals("HUB_STATE")!=(state!=null)||state!=null&&state!=0&&state!=1||age!=null&&(age<0||age>315576000000L)||latency<0||latency>8000)throw new IllegalArgumentException("Invalid PIR hub evidence.");}
 static void export(Store store,JSONObject root)throws JSONException{root.put("pir_runs",new JSONArray(store.rows("SELECT * FROM pir_runs"))).put("pir_samples",new JSONArray(store.rows("SELECT * FROM pir_samples")));validate(root);}
 static void validate(JSONObject root)throws JSONException{JSONArray ss=root.getJSONArray("sessions"),runs=root.getJSONArray("pir_runs"),samples=root.getJSONArray("pir_samples");if(runs.length()>100000||samples.length()>100000)throw new JSONException("Too much PIR evidence");Map<Long,JSONObject> sessions=new HashMap<>(),owners=new HashMap<>();for(int n=0;n<ss.length();n++)sessions.put(SensorProvenance.whole(ss.getJSONObject(n),"id"),ss.getJSONObject(n));for(int n=0;n<runs.length();n++){JSONObject run=runs.getJSONObject(n);long session=SensorProvenance.whole(run,"session");JSONObject s=sessions.get(session);String policy=SensorProvenance.text(run,"policy"),state=SensorProvenance.text(run,"state"),error=SensorProvenance.text(run,"error"),token=SensorProvenance.text(run,"token");if(run.length()!=5||s==null||owners.put(session,run)!=null||!s.optString("source").equals("tracked")||!STATES.contains(state)||!ERRORS.contains(error)||!token.isEmpty()&&!BackupRuntime.nonce(token)||state.equals("off")&&!policy.isEmpty()||!state.equals("off")&&!state.equals("error")&&policy.isEmpty()||!s.isNull("end")&&(state.equals("active")||state.equals("paused")))throw new JSONException("Invalid PIR run");if(!policy.isEmpty())try{PirConfig.validatePolicy(policy);}catch(IllegalArgumentException invalid){throw new JSONException(invalid.getMessage());}}
 Map<Long,List<RecordIntervals.Span>> pauses=new HashMap<>();JSONArray pauseRows=root.optJSONArray("pauses");if(pauseRows!=null)for(int n=0;n<pauseRows.length();n++){JSONObject p=pauseRows.getJSONObject(n);if(!p.isNull("end"))pauses.computeIfAbsent(p.getLong("session"),k->new ArrayList<>()).add(new RecordIntervals.Span(p.getLong("start"),p.getLong("end")));}
 Set<Long> ids=new HashSet<>();Map<Long,List<Long>> times=new HashMap<>();for(int n=0;n<samples.length();n++){JSONObject row=samples.getJSONObject(n);long id=SensorProvenance.whole(row,"id"),session=SensorProvenance.whole(row,"session"),time=SensorProvenance.whole(row,"time"),elapsed=SensorProvenance.whole(row,"elapsed_ms"),latency=SensorProvenance.whole(row,"latency_ms");Integer value=row.isNull("state")?null:Math.toIntExact(SensorProvenance.whole(row,"state"));Long age=row.isNull("age_ms")?null:SensorProvenance.whole(row,"age_ms");String quality=SensorProvenance.text(row,"quality");JSONObject s=sessions.get(session),run=owners.get(session);if(row.length()!=8||!row.has("state")||!row.has("age_ms")||id<=0||!ids.add(id)||s==null||run==null||run.optString("policy").isEmpty()||run.optString("state").equals("off")||elapsed<0||elapsed>SensorProvenance.MAX_SESSION||time-s.optLong("start")!=elapsed||!s.isNull("end")&&time>s.optLong("end"))throw new JSONException("Invalid PIR sample bounds");for(RecordIntervals.Span pause:pauses.getOrDefault(session,List.of()))if(time>=pause.start&&time<pause.end)throw new JSONException("PIR sample inside a tracking pause");try{checkReading(value,quality,age,latency);}catch(IllegalArgumentException invalid){throw new JSONException(invalid.getMessage());}List<Long> list=times.computeIfAbsent(session,k->new ArrayList<>());list.add(time);if(list.size()>10000)throw new JSONException("Too many PIR samples for one night");}for(List<Long> list:times.values()){Collections.sort(list);for(int n=1;n<list.size();n++)if(list.get(n).equals(list.get(n-1)))throw new JSONException("Duplicate PIR sample time");}}
 static void restore(Store store,JSONObject root,Runnable guard)throws JSONException{for(String table:TABLES)for(int n=0;n<root.getJSONArray(table).length();n++){guard.run();JSONObject j=root.getJSONArray(table).getJSONObject(n);ContentValues v=new ContentValues();v.put("session",j.getLong("session"));if(table.equals("pir_runs")){v.put("policy",j.getString("policy"));String state=j.getString("state");v.put("state",Set.of("active","paused").contains(state)?"interrupted":state);v.put("error",j.getString("error"));v.put("token","");}else{v.put("id",j.getLong("id"));v.put("time",j.getLong("time"));v.put("elapsed_ms",j.getLong("elapsed_ms"));v.put("state",j.isNull("state")?null:j.getInt("state"));v.put("quality",j.getString("quality"));v.put("age_ms",j.isNull("age_ms")?null:j.getLong("age_ms"));v.put("latency_ms",j.getLong("latency_ms"));}store.getWritableDatabase().insertOrThrow(table,null,v);}}
 private PirStore(){}
}
